item.content:encoded:
.variable-items-wrapper.button-variable-items-wrapper.wvs-style-squared {
  display: grid !important;
  grid-template-columns: repeat(2, 1fr) !important; /* 2 في الصف */
  gap: 10px !important; /* المسافة بين الأزرار */
}

.variable-items-wrapper.button-variable-items-wrapper.wvs-style-squared .variable-item {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  text-align: center !important;
  box-sizing: border-box !important;
  padding: 5px 0px !important; /* المسافة الداخلية */
  min-height: 55px !important; /* يخلي كل الأزرار بنفس الطول */
  border: 1.5px solid #000 !important; /* لون الإطار */
  border-radius: 6px !important; /* زوايا خفيفة زي اللي في الصورة */
  background-color: #fff !important;
  color: #000 !important;
  font-weight: 600 !important;
  font-size: 13px !important;
  white-space: normal !important;
  word-break: break-word !important;
  line-height: 1.4 !important;
  transition: all 0.2s ease-in-out !important;
}

/* شكل الزرار عند التحديد (زي اللي في الصورة) */
.variable-items-wrapper.button-variable-items-wrapper.wvs-style-squared .variable-item.selected {
  background-color: #0b0d1c !important; /* غامق */
  color: #fff !important; /* النص أبيض */
  border-color: #0b0d1c !important;
}





.variable-items-wrapper.button-variable-items-wrapper.wvs-style-squared
Specificity: (0,3,0)
 {
    display: inline-table !important;
    grid-template-columns: repeat(2, 1fr) !important;
    gap: 10px !important;
}





/* الكود البديل للتطبيق على تخطيطات مختلفة في WoodMart */

/* لتقليل عرض عمود الصورة إلى 40% */
.woocommerce-page .product-image-summary-wrap .woodmart-single-product .product-images-inner, 
.woocommerce-page .product-image-summary-wrap .woodmart-single-product .woodmart-product-gallery {
    width: 40% !important;
    max-width: 450px !important;
    flex: 0 0 40% !important; /* مهم لنظام Flexbox/Grid */
}

/* لزيادة عرض عمود المحتوى إلى 60% */
.woocommerce-page .product-image-summary-wrap .woodmart-single-product .summary-inner,
.woocommerce-page .product-image-summary-wrap .woodmart-single-product .entry-summary {
    width: 60% !important;
    flex: 0 0 60% !important; /* مهم لنظام Flexbox/Grid */
}

/* لضمان تناسق الصورة داخل العمود */
.woodmart-single-product .product-images-inner img,
.woodmart-single-product .woodmart-product-gallery img {
    height: auto !important;
    max-width: 100% !important;
}


@media (min-width: 769px) {
    .elementor-797 .elementor-element.elementor-element-9faa65d
Specificity: (0,3,0)
 {
        --width: 48%;
    }
}

