","size":""},"background_slideshow_gallery":[],"background_hover_image":{"url":"","id":"","size":""},"background_hover_video_fallback":{"url":"","id":"","size":""},"background_hover_slideshow_gallery":[],"background_overlay_image":{"url":"","id":"","size":""},"background_overlay_video_fallback":{"url":"","id":"","size":""},"background_overlay_slideshow_gallery":[],"background_overlay_hover_image":{"url":"","id":"","size":""},"background_overlay_hover_video_fallback":{"url":"","id":"","size":""},"background_overlay_hover_slideshow_gallery":[]},"elements":[{"id":"641fd9b8","elType":"widget","settings":{"image":{"id":28167,"url":"https://waqfehsan.org.sa/wp-content/uploads/2026/08/02.jpg.jpeg"},"width":{"unit":"%","size":100,"sizes":[]},"scroll_y":-80,"width_mobile":{"unit":"%","size":100,"sizes":[]},"space_mobile":{"unit":"%","size":100,"sizes":[]},"height_mobile":{"unit":"px","size":153,"sizes":[]},"_background_image":{"url":"","id":"","size":""},"_background_video_fallback":{"url":"","id":"","size":""},"_background_slideshow_gallery":[],"_background_hover_image":{"url":"","id":"","size":""},"_background_hover_video_fallback":{"url":"","id":"","size":""},"_background_hover_slideshow_gallery":[],"_mask_image":{"url":"","id":"","size":""}},"elements":[],"widgetType":"image"}],"isInner":true}],"isInner":true,"isLocked":true}]}],"isInner":false},{"id":"76523fe1","elType":"container","settings":{"flex_direction":"row","css_classes":"ma-waqf-trust","scroll_y":-80,"custom_css":"/* ============================================
   شريط الثقة تحت الهيرو — وقف إحسان
   ============================================ */

.ma-waqf-trust {
	background: #fff;
	border: 1px solid #ece9e2;
	border-radius: 14px;
	overflow: hidden;
}

/* صف الأعمدة الثلاثة بارتفاع متساوٍ */
.ma-waqf-trust > .elementor-container {
	align-items: stretch;
}

/* ---- كل عمود = بطاقة أفقية (أيقونة + نص) ---- */
.ma-waqf-trust .ma-waqf-trust__item {
	display: flex !important;
	flex-direction: row;   /* الأيقونة يمين، النص يساره */
	align-items: center;
	justify-content: flex-start;
	gap: 14px;
	padding: 20px 18px;
	border-left: 1px solid #ece9e2;
	height: 100%;
}

/* إزالة الفاصل من آخر عمود */
.ma-waqf-trust .elementor-column:last-child .ma-waqf-trust__item {
	border-left: 0;
}

/* ---- الأيقونة: عرض ثابت، لا تمتد ---- */
.ma-waqf-trust .ma-waqf-trust__icon {
	flex: 0 0 48px;
	width: 48px !important;
	max-width: 48px;
	height: 48px;
	border-radius: 12px;
	background: #e7f0ec;
	display: flex;
	align-items: center;
	justify-content: center;
	margin: 0 !important;
	padding: 0 !important;
}

.ma-waqf-trust .ma-waqf-trust__icon .elementor-icon,
.ma-waqf-trust .ma-waqf-trust__icon i,
.ma-waqf-trust .ma-waqf-trust__icon svg {
	color: #0f5a4a !important;
	fill: #0f5a4a !important;
	font-size: 24px;
	width: 24px;
	height: 24px;
}

/* ---- حاوية النص: تأخذ باقي العرض ---- */
.ma-waqf-trust .ma-waqf-trust__text {
	flex: 1 1 auto;
	width: auto !important;
	text-align: right;
	display: flex;
	flex-direction: column;
	gap: 8px;
}

/* عناصر Elementor الداخلية بلا هوامش زائدة */
.ma-waqf-trust .ma-waqf-trust__text .elementor-widget {
	margin: 0 !important;
}

/* ---- العنوان ---- */
.ma-waqf-trust .ma-waqf-trust__title,
.ma-waqf-trust .ma-waqf-trust__title * {
	font-size: 15px !important;
	font-weight: 600 !important;
	color: #1c1c1a !important;
	margin: 0 !important;
	line-height: 1.4 !important;
}

/* ---- النص الفرعي ---- */
.ma-waqf-trust .ma-waqf-trust__sub,
.ma-waqf-trust .ma-waqf-trust__sub * {
	font-size: 12px !important;
	color: #8a8a84 !important;
	margin: 0 !important;
	line-height: 1.5 !important;
}

/* ---- الجوال: عمود واحد ---- */
@media (max-width: 767px) {
	.ma-waqf-trust .ma-waqf-trust__item {
		border-left: 0 !important;
		border-bottom: 1px solid #ece9e2;
	}
	.ma-waqf-trust .elementor-column:last-child .ma-waqf-trust__item {
		border-bottom: 0;
	}
