.ma-sec-head {
	text-align: center;
	margin-bottom: 8px;
	padding:20px ;
}

.ma-sec-head .ma-sec-head__icon {
	width: 46px;
	height: 46px;
	border-radius: 12px;
	background: #e7f0ec;
	display: flex;
	align-items: center;
	justify-content: center;
	margin: 0 auto 5px !important;
}

.ma-sec-head .ma-sec-head__icon .elementor-icon,
.ma-sec-head .ma-sec-head__icon i,
.ma-sec-head .ma-sec-head__icon svg {
	color: #0f5a4a !important;
	fill: #0f5a4a !important;
	font-size: 24px;
	width: 24px;
	height: 24px;
}

.ma-sec-head .ma-sec-head__title,
.ma-sec-head .ma-sec-head__title * {
	font-size: 22px !important;
	font-weight: 600 !important;
	color: #1c1c1a !important;
	margin: 0 0 0px !important;
	line-height: 1.4 !important;
}

.ma-sec-head .ma-sec-head__sub,
.ma-sec-head .ma-sec-head__sub * {
	font-size: 13px !important;
	color: #8a8a84 !important;
	margin: 0 !important;
	line-height: 1.7 !important;
}

/* الخط الذهبي أسفل العنوان */
.ma-sec-head::after {
	content: "";
	display: block;
	width: 56px;
	height: 3px;
	background: #c9a227;
	border-radius: 3px;
	margin: 14px auto 0;
}

@media (max-width: 767px) {
	.ma-sec-head .ma-sec-head__title,
	.ma-sec-head .ma-sec-head__title * {
		font-size: 19px !important;
	}
