":"","id":"","size":""},"_background_slideshow_gallery":[],"_background_hover_image":{"url":"","id":"","size":""},"_background_hover_video_fallback":{"url":"","id":"","size":""},"_background_hover_slideshow_gallery":[],"_mask_image":{"url":"","id":"","size":""}},"elements":[],"widgetType":"text-editor"}],"isInner":true},{"id":"4a1380f2","elType":"widget","settings":{"shortcode":"[products category="الافطار-والسقيا" limit="4" columns="4"]","scroll_y":-80,"_background_image":{"url":"","id":"","size":""},"_background_video_fallback":{"url":"","id":"","size":""},"_background_slideshow_gallery":[],"_background_hover_image":{"url":"","id":"","size":""},"_background_hover_video_fallback":{"url":"","id":"","size":""},"_background_hover_slideshow_gallery":[],"_mask_image":{"url":"","id":"","size":""}},"elements":[],"widgetType":"shortcode"}],"isInner":false},{"id":"6733a0d6","elType":"container","settings":{"flex_direction":"row","html_tag":"section","css_classes":" ma-stats","scroll_y":-80,"custom_css":"/* ===== شريط الأرقام / الحقائق (3 أعمدة) ===== */

.ma-stats {
	background: #faf8f5;
	border: 1px solid #ece9e2;
	border-radius: 14px;
	padding: 24px 12px;
}

.ma-stats > .elementor-container {
	align-items: stretch;
}

.ma-stats .ma-stats__item {
	text-align: center;
	padding: 4px 12px;
	border-left: 1px solid #ece9e2;
	height: 100%;
}

/* آخر عمود (الأيسر في RTL) بلا فاصل */
.ma-stats .elementor-column:last-child .ma-stats__item {
	border-left: 0;
}

/* إزالة هامش ويدجت Elementor الافتراضي */
.ma-stats .elementor-widget {
	margin-bottom: 0 !important;
}

/* ---- الرقم / النص الكبير ---- */
.ma-stats .ma-stats__num,
.ma-stats .ma-stats__num * {
	font-size: 30px !important;
	font-weight: 600 !important;
	color: #0f5a4a !important;
	margin: 0 !important;
	line-height: 1.3 !important;
}

/* ---- الوصف ---- */
.ma-stats .ma-stats__label,
.ma-stats .ma-stats__label * {
	font-size: 12px !important;
	color: #8a8a84 !important;
	margin: 4px 0 0 !important;
	line-height: 1.6 !important;
}

/* ---- الجوال: عمود واحد ---- */
@media (max-width: 767px) {
	.ma-stats .ma-stats__num,
	.ma-stats .ma-stats__num * {
		font-size: 26px !important;
	}
	.ma-stats .ma-stats__item {
		border-left: 0 !important;
		border-bottom: 1px solid #ece9e2;
		padding: 16px 12px;
	}
	.ma-stats .elementor-column:last-child .ma-stats__item {
		border-bottom: 0;
	}
