"settings":{"title":"الإهداءات والبرامج","scroll_y":-80,"align":"center","_css_classes":"ma-sec-head__title","_background_image":{"url":"","id":"","size":""},"_background_video_fallback":{"url":"","id":"","size":""},"_background_slideshow_gallery":[],"_background_hover_image":{"url":"","id":"","size":""},"_background_hover_video_fallback":{"url":"","id":"","size":""},"_background_hover_slideshow_gallery":[],"_mask_image":{"url":"","id":"","size":""}},"elements":[],"widgetType":"heading"},{"id":"54b30c9a","elType":"widget","settings":{"editor":"<p>إطعام وسقيا ضيوف الرحمن في أطهر البقاع)</p>","align":"center","_css_classes":" ma-sec-head__sub","scroll_y":-80,"_background_image":{"url":"","id":"","size":""},"_background_video_fallback":{"url":"","id":"","size":""},"_background_slideshow_gallery":[],"_background_hover_image":{"url":"","id":"","size":""},"_background_hover_video_fallback":{"url":"","id":"","size":""},"_background_hover_slideshow_gallery":[],"_mask_image":{"url":"","id":"","size":""}},"elements":[],"widgetType":"text-editor"}],"isInner":true},{"id":"1296cec2","elType":"widget","settings":{"shortcode":"[products category="متنوع" limit="3" columns="3"]","scroll_y":-80,"_background_image":{"url":"","id":"","size":""},"_background_video_fallback":{"url":"","id":"","size":""},"_background_slideshow_gallery":[],"_background_hover_image":{"url":"","id":"","size":""},"_background_hover_video_fallback":{"url":"","id":"","size":""},"_background_hover_slideshow_gallery":[],"_mask_image":{"url":"","id":"","size":""}},"elements":[],"widgetType":"shortcode"}],"isInner":true}],"isInner":false},{"id":"21cb8d72","elType":"container","settings":{"flex_direction":"column","flex_gap":{"column":"5","row":"5","isLinked":true,"unit":"px","size":5},"html_tag":"section","css_classes":"ma-shares","scroll_y":-80,"custom_css":"/* ============================================
   قسم الأسهم الخمسة — وقف إحسان (بلا أزرار، بلا بطاقة مميّزة)
   ============================================ */
.ma-shares {
	background: #faf8f5;
	border-radius: 14px;
	padding: 26px 18px;
}
.ma-shares .elementor-widget { margin-bottom: 0 !important; }

/* ---- الترويسة ---- */
.ma-shares .ma-shares__eyebrow {
	display: inline-block;
	font-size: 12px !important;
	font-weight: 600 !important;
	color: #0f5a4a !important;
	background: #e7f0ec;
	padding: 10px 40px;
	border-radius: 20px;
	margin: 0 auto 10px !important;
}
.ma-shares .ma-shares__title,
.ma-shares .ma-shares__title * {
	font-size: 22px !important;
	font-weight: 600 !important;
	color: #1c1c1a !important;
	text-align: center;
	margin: 0 0 6px !important;
}
.ma-shares .ma-shares__intro,
.ma-shares .ma-shares__intro * {
	font-size: 13px !important;
	color: #6b6b66 !important;
	text-align: center;
	line-height: 1.8 !important;
	max-width: 560px;
	margin: 0 auto 22px !important;
}

/* ---- شبكة البطاقات ---- */
.ma-shares .ma-shares__grid > .elementor-container {
	align-items: stretch;
}

/* ---- البطاقة ---- */
.ma-shares .ma-shares__card {
	background: #fff;
	border: 1px solid #ece9e2;
	border-radius: 14px;
	padding: 18px 12px;
	text-align: center;
	height: 100%;
	display: flex;
	flex-direction: column;
	position: relative;
	transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}

/* تأثير المرور (hover) */
.ma-shares .ma-shares__card:hover {
	transform: translateY(-6px);
	box-shadow: 0 14px 30px rgba(15, 90, 74, 0.12);
	border-color: #cfe0d9;
}

/* الأيقونة */
.ma-shares .ma-shares__icon {
	width: 44px;
	height: 44px;
	border-radius: 50%;
	background: #e7f0ec;
	display: flex;
	align-items: center;
	justify-content: center;
	margin: 0 auto 12px !important;
	transition: background 0.22s ease;
}

/* الأيقونة عند المرور */
.ma-shares .ma-shares__card:hover .ma-shares__icon {
	background: #0f5a4a;
}
.ma-shares .ma-shares__card:hover .ma-shares__icon .elementor-icon,
.ma-shares .ma-shares__card:hover .ma-shares__icon i,
.ma-shares .ma-shares__card:hover .ma-shares__icon svg {
	color: #fff !important;
	fill: #fff !important;
}

.ma-shares .ma-shares__icon .elementor-icon,
.ma-shares .ma-shares__icon i,
.ma-shares .ma-shares__icon svg {
	color: #0f5a4a !important;
	fill: #0f5a4a !important;
	font-size: 22px;
	width: 22px;
	height: 22px;
	transition: color 0.22s ease, fill 0.22s ease;
}

/* الاسم */
/* اسم السهم — سطر واحد ثابت */
.ma-shares .ma-shares__name {
	min-height: 3em;
	display: flex;
	align-items: center;
	justify-content: center;
}

/* الوصف — يحجز ارتفاع ثابت للجميع */
.ma-shares .ma-shares__desc {
	min-height: 4.6em;   /* ~3 أسطر — اضبط حسب أطول وصف */
	display: flex;
	align-items: center;
	justify-content: center;
	flex: 1 1 auto;
}

/* ---- الجوال ---- */
@media (max-width: 767px) {
	.ma-shares .ma-shares__title,
	.ma-shares .ma-shares__title * { font-size: 19px !important; }

	/* تقليل حركة المرور على اللمس */
	.ma-shares .ma-shares__card:hover {
		transform: none;
	}
}

@media (prefers-reduced-motion: reduce) {
	.ma-shares .ma-shares__card,
	.ma-shares .ma-shares__icon,
	.ma-shares .ma-shares__icon .elementor-icon,
	.ma-shares .ma-shares__icon i,
	.ma-shares .ma-shares__icon svg {
		transition: none !important;
	}
	.ma-shares .ma-shares__card:hover {
		transform: none;
	}
