<!-- /wp:paragraph -->","scroll_y":-80},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"55e7f77","elType":"container","settings":{"flex_direction":"column","scroll_y":-80},"elements":[{"id":"29b8d55","elType":"widget","settings":{"html":"<style>
.projects-section {
  text-align: center;
  padding: 80px 20px;
  background-color: #ffffff;
  font-family: "Cairo", sans-serif;
}
.projects-section h2 {
  color: #0D656D;
  font-size: 34px;
  margin-bottom: 50px;
  font-weight: 700;
  position: relative;
  display: inline-block;
}
.projects-section h2::after {
  content: "";
  display: block;
  width: 80px;
  height: 3px;
  background: #0D656D;
  margin: 10px auto 0;
  border-radius: 2px;
}

.project-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 30px;
  justify-content: center;
  align-items: stretch;
}

.project-card {
  background: #fff;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 6px 18px rgba(0,0,0,0.1);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.project-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 10px 25px rgba(0,0,0,0.15);
}

.project-card img {
  width: 100%;
  height: 230px;
  object-fit: cover;
}

.project-content {
  padding: 25px;
  text-align: center;
}

.project-content h3 {
  color: #222;
  font-size: 21px;
  font-weight: 600;
  margin-bottom: 12px;
}

.progress-bar-container {
  background-color: #eee;
  border-radius: 10px;
  overflow: hidden;
  height: 10px;
  margin: 10px 0 12px;
}
.progress-bar {
  background-color: #0D656D;
  height: 100%;
  width: 60%; /* نسبة التبرع */
  transition: width 0.5s ease;
}

.donation-info {
  font-size: 15px;
  color: #666;
  margin-bottom: 18px;
}

.donate-btn {
  display: inline-block;
  background-color: #0D656D;
  color: #fff;
  padding: 10px 28px;
  border-radius: 10px;
  text-decoration: none;
  font-weight: 600;
  transition: all 0.3s ease;
}
.donate-btn:hover {
  background-color: #0b5057;
  transform: scale(1.05);
}

/* 🟢 موبايل */
@media (max-width: 768px) {
  .projects-section h2 {
    font-size: 26px;
  }
  .project-content h3 {
    font-size: 18px;
  }
  .donate-btn {
    padding: 9px 22px;
    font-size: 15px;
  }
}
</style>

<section class="projects-section">
  <h2>مشاريع تنتظر دعمكم</h2>
  <div class="project-grid">
    
    <!-- المشروع الأول -->
    <div class="project-card">
      <img src="https://via.placeholder.com/400x250" alt="مشروع 1">
      <div class="project-content">
        <h3>دعم الأسر المتعففة</h3>
        <div class="progress-bar-container">
          <div class="progress-bar" style="width: 70%;"></div>
        </div>
        <div class="donation-info">تم جمع 7,000 ريال من أصل 10,000 ريال</div>
        <a href="#" class="donate-btn">تبرع الآن</a>
      </div>
    </div>

    <!-- المشروع الثاني -->
    <div class="project-card">
      <img src="https://via.placeholder.com/400x250" alt="مشروع 2">
      <div class="project-content">
        <h3>كفالة الأيتام</h3>
        <div class="progress-bar-container">
          <div class="progress-bar" style="width: 45%;"></div>
        </div>
        <div class="donation-info">تم جمع 4,500 ريال من أصل 10,000 ريال</div>
        <a href="#" class="donate-btn">تبرع الآن</a>
      </div>
    </div>

    <!-- المشروع الثالث -->
    <div class="project-card">
      <img src="https://via.placeholder.com/400x250" alt="مشروع 3">
      <div class="project-content">
        <h3>بناء مسجد صغير</h3>
        <div class="progress-bar-container">
          <div class="progress-bar" style="width: 90%;"></div>
        </div>
        <div class="donation-info">تم جمع 9,000 ريال من أصل 10,000 ريال</div>
        <a href="#" class="donate-btn">تبرع الآن</a>
      </div>
    </div>

  </div>
</section>
