","_css_classes":"ma-categ-title","scroll_y":-80},"elements":[],"widgetType":"heading"},{"id":"857b0e9","elType":"widget","settings":{"editor":"<div class="browse__head"><p class="browse__sub">مرّر لاستكشاف جميع أبواب الإحسان</p></div>","scroll_y":-80,"hide_desktop":"hidden-desktop","hide_tablet":"hidden-tablet"},"elements":[],"widgetType":"text-editor"},{"id":"52389cc","elType":"container","settings":{"content_width":"full","flex_direction":"row","css_classes":" ma-catnav   ","scroll_y":-80,"custom_css":"html { scroll-behavior: smooth; }

#sec-abwab, #sec-guests, #sec-waqf, #sec-addiction {
	scroll-margin-top: 110px;
}

/* Heading above the pill row */
html body .ma-categ-title {
	text-align: center !important;
	font-size: 22px !important;
	font-weight: 700 !important;
	color: #0C3B2E !important;
	margin: 0 0 16px !important;
}

/* Pill row container — desktop: horizontal, scrollable if it overflows */
html body .ma-catnav {
	display: flex !important;
	flex-wrap: nowrap !important;
	align-items: center !important;
	justify-content: center !important;
	gap: 10px !important;
	background: #0C3B2E !important;
	padding: 12px 16px !important;
	border-radius: 14px !important;
	overflow-x: auto !important;
	overflow-y: hidden !important;
	-ms-overflow-style: none;
	scrollbar-width: none;
}
html body .ma-catnav::-webkit-scrollbar { display: none; }

html body .ma-catnav > * {
	flex: 0 0 auto !important;
	width: auto !important;
}

/* The pill itself — only the outer element carries the visible box */
html body .ma-cat-pill {
	display: inline-flex !important;
	align-items: center !important;
	justify-content: center !important;
	background: rgba(255,255,255,0.08) !important;
	border: 1px solid rgba(255,255,255,0.28) !important;
	border-radius: 24px !important;
	padding: 11px 22px !important;
	margin: 0 !important;
	line-height: 1.4 !important;
	white-space: nowrap !important;
	color: #ffffff !important;
	text-decoration: none !important;
	transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease;
	box-shadow: none !important;
	min-height: 0 !important;
	height: auto !important;
}

/* Everything inside is stripped to plain inherited text — no nested box */
html body .ma-cat-pill * {
	background: transparent !important;
	border: none !important;
	border-radius: 0 !important;
	padding: 0 !important;
	margin: 0 !important;
	min-height: 0 !important;
	height: auto !important;
	color: inherit !important;
	-webkit-text-fill-color: inherit !important;
	font-size: 14px !important;
	font-weight: 700 !important;
	line-height: 1.4 !important;
}

html body .ma-cat-pill:hover,



/* Mobile — 2x2 grid, no scrolling needed, all 4 visible at once */
@media (max-width: 767px) {
	html body .ma-categ-title {
		font-size: 18px !important;
		margin-bottom: 12px !important;
	}

	html body .ma-catnav {
		display: grid !important;
		grid-template-columns: 1fr 1fr !important;
		overflow: visible !important;
		padding: 10px !important;
		gap: 8px !important;
	}

	html body .ma-catnav > * {
		width: 100% !important;
	}

	html body .ma-cat-pill {
		width: 100% !important;
		padding: 12px 10px !important;
		text-align: center !important;
	}

	html body .ma-cat-pill * {
		font-size: 13px !important;
	}

	#sec-abwab, #sec-guests, #sec-waqf, #sec-addiction {
		scroll-margin-top: 90px;
	}
