	padding:20px ;
}

.ma-sec-head .ma-sec-head__icon {
	width: 46px;
	height: 46px;
	border-radius: 12px;
	background: #e7f0ec;
	display: flex;
	align-items: center;
	justify-content: center;
	margin: 0 auto 5px !important;
