","scroll_y":-80,"_element_id":"sec-addiction"},"elements":[],"widgetType":"shortcode"}],"isInner":true}],"isInner":false},{"id":"504d5def","elType":"container","settings":{"flex_direction":"column","flex_gap":{"column":"5","row":"5","isLinked":true,"unit":"px","size":5},"html_tag":"section","css_classes":"ma-shares","scroll_y":-80,"custom_css":"/* ============================================
   قسم الأسهم الخمسة — وقف إحسان (بلا أزرار، بلا بطاقة مميّزة)
   ============================================ */
.ma-shares {
	background: #faf8f5;
	border-radius: 14px;
	padding: 26px 18px;
}
.ma-shares .elementor-widget { margin-bottom: 0 !important; }

/* ---- الترويسة ---- */
.ma-shares .ma-shares__eyebrow {
	display: inline-block;
	font-size: 12px !important;
	font-weight: 600 !important;
	color: #0f5a4a !important;
	background: #e7f0ec;
	padding: 10px 40px;
	border-radius: 20px;
	margin: 0 auto 10px !important;
}
.ma-shares .ma-shares__title,
.ma-shares .ma-shares__title * {
	font-size: 22px !important;
	font-weight: 600 !important;
	color: #1c1c1a !important;
	text-align: center;
	margin: 0 0 6px !important;
}
.ma-shares .ma-shares__intro,
.ma-shares .ma-shares__intro * {
	font-size: 13px !important;
	color: #6b6b66 !important;
	text-align: center;
	line-height: 1.8 !important;
	max-width: 560px;
	margin: 0 auto 22px !important;
}

/* ---- شبكة البطاقات ---- */
.ma-shares .ma-shares__grid > .elementor-container {
	align-items: stretch;
}

/* ---- البطاقة ---- */
.ma-shares .ma-shares__card {
	background: #fff;
	border: 1px solid #ece9e2;
	border-radius: 14px;
	padding: 18px 12px;
	text-align: center;
	height: 100%;
	display: flex;
	flex-direction: column;
	position: relative;
	transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}

/* تأثير المرور (hover) */
.ma-shares .ma-shares__card:hover {
	transform: translateY(-6px);
	box-shadow: 0 14px 30px rgba(15, 90, 74, 0.12);
	border-color: #cfe0d9;
}

/* الأيقونة */
.ma-shares .ma-shares__icon {
	width: 44px;
	height: 44px;
	border-radius: 50%;
	background: #e7f0ec;
	display: flex;
	align-items: center;
	justify-content: center;
	margin: 0 auto 12px !important;
	transition: background 0.22s ease;
}

/* الأيقونة عند المرور */
.ma-shares .ma-shares__card:hover .ma-shares__icon {
	background: #0f5a4a;
}
.ma-shares .ma-shares__card:hover .ma-shares__icon .elementor-icon,
.ma-shares .ma-shares__card:hover .ma-shares__icon i,
.ma-shares .ma-shares__card:hover .ma-shares__icon svg {
	color: #fff !important;
	fill: #fff !important;
}

.ma-shares .ma-shares__icon .elementor-icon,
.ma-shares .ma-shares__icon i,
.ma-shares .ma-shares__icon svg {
	color: #0f5a4a !important;
	fill: #0f5a4a !important;
	font-size: 22px;
	width: 22px;
	height: 22px;
	transition: color 0.22s ease, fill 0.22s ease;
}

/* الاسم */
/* اسم السهم — سطر واحد ثابت */
.ma-shares .ma-shares__name {
	min-height: 3em;
	display: flex;
	align-items: center;
	justify-content: center;
}

/* الوصف — يحجز ارتفاع ثابت للجميع */
.ma-shares .ma-shares__desc {
	min-height: 4.6em;   /* ~3 أسطر — اضبط حسب أطول وصف */
	display: flex;
	align-items: center;
	justify-content: center;
	flex: 1 1 auto;
}

/* ---- الجوال ---- */
@media (max-width: 767px) {
	.ma-shares .ma-shares__title,
	.ma-shares .ma-shares__title * { font-size: 19px !important; }

	/* تقليل حركة المرور على اللمس */
	.ma-shares .ma-shares__card:hover {
		transform: none;
	}
}

@media (prefers-reduced-motion: reduce) {
	.ma-shares .ma-shares__card,
	.ma-shares .ma-shares__icon,
	.ma-shares .ma-shares__icon .elementor-icon,
	.ma-shares .ma-shares__icon i,
	.ma-shares .ma-shares__icon svg {
		transition: none !important;
	}
	.ma-shares .ma-shares__card:hover {
		transform: none;
	}
}","_title":"definiton-section"},"elements":[{"id":"5ab1580c","elType":"widget","settings":{"editor":"<p>قبل أن تختار</p>","align":"center","_css_classes":"ma-shares__eyebrow","scroll_y":-80},"elements":[],"widgetType":"text-editor"},{"id":"5e64e763","elType":"widget","settings":{"title":"ما معنى الأسهم؟","align":"center","_css_classes":" ma-shares__title","scroll_y":-80},"elements":[],"widgetType":"heading"},{"id":"4f2ca6f8","elType":"widget","settings":{"editor":"<div><div>كل سهم بابٌ من أبواب الأجر وحصة ثابتة في الوقف يجري ثوابها ما بقي أثره. اختر ما يناسبك.</div></div>","align":"center","_css_classes":" ma-shares__intro","scroll_y":-80},"elements":[],"widgetType":"text-editor"},{"id":"1054289b","elType":"container","settings":{"content_width":"full","flex_direction":"row","css_classes":"ma-shares__grid","scroll_y":-80,"_title":"inner-columns"},"elements":[{"id":"7998cd59","elType":"container","settings":{"content_width":"full","flex_gap":{"column":"8","row":"8","isLinked":true,"unit":"px","size":8},"css_classes":"ma-shares__card","scroll_y":-80,"_title":"card-1"},"elements":[{"id":"7cbdd2cb","elType":"widget","settings":{"selected_icon":{"value":"fas fa-seedling","library":"fa-solid"},"_css_classes":" ma-shares__icon","scroll_y":-80},"elements":[],"widgetType":"icon"},{"id":"41d3284f","elType":"widget","settings":{"title":"سهم البركة
