igation_next_icon_vertical_position_mobile":{"unit":"px","size":22,"sizes":[]},"arrows_size_mobile":{"unit":"px","size":13,"sizes":[]},"arrows_size":{"unit":"px","size":32,"sizes":[]},"dots_size_mobile":{"unit":"px","size":6,"sizes":[]},"__globals__":{"arrow_normal_color":"globals/colors?id=accent"},"slides_to_show_tablet":"1"},"elements":[{"id":"1e94282b","elType":"container","settings":{"_title":"Slide #2","scroll_y":-80},"elements":[{"id":"b30088a","elType":"container","settings":{"flex_direction":"column","content_width":"full","scroll_y":-80},"elements":[{"id":"5cfa31b4","elType":"widget","settings":{"image":{"id":"28166","url":"https://waqfehsan.org.sa/wp-content/uploads/2026/08/01.jpg.jpeg"},"width":{"unit":"%","size":100,"sizes":[]},"scroll_y":-80,"height_mobile":{"unit":"px","size":153,"sizes":[]},"image_size":"full"},"elements":[],"widgetType":"image"}],"isInner":true}],"isInner":true,"isLocked":true},{"id":"6aeed94a","elType":"container","settings":{"_title":"Slide #1","scroll_y":-80},"elements":[{"id":"7f053700","elType":"container","settings":{"flex_direction":"column","content_width":"full","scroll_y":-80},"elements":[{"id":"4a9c36ba","elType":"widget","settings":{"image":{"id":"28167","url":"https://waqfehsan.org.sa/wp-content/uploads/2026/08/02.jpg.jpeg"},"width":{"unit":"%","size":100,"sizes":[]},"scroll_y":-80,"width_mobile":{"unit":"%","size":100,"sizes":[]},"space_mobile":{"unit":"%","size":100,"sizes":[]},"height_mobile":{"unit":"px","size":153,"sizes":[]}},"elements":[],"widgetType":"image"}],"isInner":true}],"isInner":true,"isLocked":true}]}],"isInner":false},{"id":"46c08db4","elType":"container","settings":{"flex_direction":"row","css_classes":"ma-waqf-trust","scroll_y":-80,"custom_css":"/* ============================================
   شريط الثقة تحت الهيرو — وقف إحسان
   ============================================ */

.ma-waqf-trust {
	background: #fff;
	border: 1px solid #ece9e2;
	border-radius: 14px;
	overflow: hidden;
}

/* صف الأعمدة الثلاثة بارتفاع متساوٍ */
.ma-waqf-trust > .elementor-container {
	align-items: stretch;
}

/* ---- كل عمود = بطاقة أفقية (أيقونة + نص) ---- */
.ma-waqf-trust .ma-waqf-trust__item {
	display: flex !important;
	flex-direction: row;   /* الأيقونة يمين، النص يساره */
	align-items: center;
	justify-content: flex-start;
	gap: 14px;
	padding: 20px 18px;
	border-left: 1px solid #ece9e2;
	height: 100%;
}

/* إزالة الفاصل من آخر عمود */
.ma-waqf-trust .elementor-column:last-child .ma-waqf-trust__item {
	border-left: 0;
}

/* ---- الأيقونة: عرض ثابت، لا تمتد ---- */
.ma-waqf-trust .ma-waqf-trust__icon {
	flex: 0 0 48px;
	width: 48px !important;
	max-width: 48px;
	height: 48px;
	border-radius: 12px;
	background: #e7f0ec;
	display: flex;
	align-items: center;
	justify-content: center;
	margin: 0 !important;
	padding: 0 !important;
}

.ma-waqf-trust .ma-waqf-trust__icon .elementor-icon,
.ma-waqf-trust .ma-waqf-trust__icon i,
.ma-waqf-trust .ma-waqf-trust__icon svg {
	color: #0f5a4a !important;
	fill: #0f5a4a !important;
	font-size: 24px;
	width: 24px;
	height: 24px;
}

/* ---- حاوية النص: تأخذ باقي العرض ---- */
.ma-waqf-trust .ma-waqf-trust__text {
	flex: 1 1 auto;
	width: auto !important;
	text-align: right;
	display: flex;
	flex-direction: column;
	gap: 8px;
}

/* عناصر Elementor الداخلية بلا هوامش زائدة */
.ma-waqf-trust .ma-waqf-trust__text .elementor-widget {
	margin: 0 !important;
}

/* ---- العنوان ---- */
.ma-waqf-trust .ma-waqf-trust__title,
.ma-waqf-trust .ma-waqf-trust__title * {
	font-size: 15px !important;
	font-weight: 600 !important;
	color: #1c1c1a !important;
	margin: 0 !important;
