	background: #faf8f5;
	border: 1px solid #ece9e2;
	border-radius: 14px;
	padding: 24px 12px;
}

.ma-stats > .elementor-container {
	align-items: stretch;
}

.ma-stats .ma-stats__item {
	text-align: center;
	padding: 4px 12px;
	border-left: 1px solid #ece9e2;
	height: 100%;
}

/* آخر عمود (الأيسر في RTL) بلا فاصل */
.ma-stats .elementor-column:last-child .ma-stats__item {
	border-left: 0;
}

