 وقف إحسان — Single Product Page Image Sizing
 Added: August 2026
 =================================================== */

/* --- Main product image: cap the height --- */
.single-product .woocommerce-product-gallery img,
.single-product .wd-product-images img,
.single-product .wd-carousel img {
 max-width: 100%;
 height: auto;
 max-height: 500px;
 object-fit: contain;
}

/* --- Gallery column: stop it dominating the layout --- */
.single-product .woocommerce-product-gallery,
.single-product .wd-product-images {
 max-width: 500px;
 margin-left: auto;
 margin-right: auto;
}

/* --- Tablet --- */
@media (max-width: 1024px) {
 .single-product .woocommerce-product-gallery img,
 .single-product .wd-product-images img,
 .single-product .wd-carousel img {
 max-height: 400px;
 }
}

/* --- Mobile --- */
@media (max-width: 768px) {
 .single-product .woocommerce-product-gallery img,
 .single-product .wd-product-images img,
 .single-product .wd-carousel img {
 max-height: 300px;
 }

 .single-product .woocommerce-product-gallery,
 .single-product .wd-product-images {
 max-width: 100%;
 }
